static inline void qede_reuse_page ( struct qede_rx_queue * rxq , struct sw_rx_data * curr_cons ) { struct eth_rx_bd * rx_bd_prod = qed_chain_produce ( & rxq -> rx_bd_ring ) ; struct sw_rx_data * curr_prod ; dma_addr_t new_mapping ; curr_prod = & rxq -> sw_rx_ring [ rxq -> sw_rx_prod & NUM_RX_BDS_MAX ] ; * curr_prod = * curr_cons ; new_mapping = curr_prod -> mapping + curr_prod -> page_offset ; rx_bd_prod -> addr . hi = cpu_to_le32 ( upper_32_bits ( new_mapping ) ) ; rx_bd_prod -> addr . lo = cpu_to_le32 ( lower_32_bits ( new_mapping ) ) ; rxq -> sw_rx_prod ++ ; curr_cons -> data = NULL ; } 